var TINH_MAP   = {"Hiếu":["BNH","HNI","HPG","HYN","PTO","QNH","TNN"],"Đăng":["DLK","HUE"],"Đạt":["AGG","CMU","CTO","DNI","DTP","HCM","TNH","VLG"]};
